function libraryToolbarModel() {
  const capabilities = { close: { enabled: true, dispatch: 'internal:close-library' }, help: { enabled: true, dispatch: 'command:ikemen.help.open' } };
  for (const [slotId, command] of Object.entries(LIBRARY_TOOLBAR_COMMANDS)) capabilities[slotId] = { enabled: true, dispatch: `command:${command}` };
  return adapt('authoring.library', capabilities);
}

function escape(value) { return String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
async function cachedSourceRevision(cache,filename){
  const key=path.resolve(filename).toLowerCase();if(cache.has(key))return cache.get(key);
  const pending=(async()=>{const document=await vscode.workspace.openTextDocument(vscode.Uri.file(filename)),text=document.getText();return{document,text,hash:crypto.createHash('sha256').update(text).digest('hex')};})();
  cache.set(key,pending);return pending;
}
function ids(key) { return extensionContext.globalState.get(key, []); }
function visible(item, enabled=false, capabilities={}){return Boolean(item)&&(!item.nightlyString||enabled===true)&&entryAvailable(item,capabilities);}
function favorites(options={}) { return ids(FAVORITES_KEY).map(catalog.itemById).filter(item=>visible(item,options.nightlyStringsEnabled,options.capabilities)); }
function recents(options={}) { return ids(RECENTS_KEY).map(catalog.itemById).filter(item=>visible(item,options.nightlyStringsEnabled,options.capabilities)); }
async function toggleFavorite(id, current=()=>true) {
  if(!catalog.itemById(id))return false;
  const mutate=async()=>{if(!current())return false;const values=ids(FAVORITES_KEY),next=values.includes(id)?values.filter(value=>value!==id):[...values,id];if(!current())return false;await extensionContext.globalState.update(FAVORITES_KEY,next);if(!current())return true;await vscode.commands.executeCommand('ikemen.authoring.refreshSidebar');return true;};
  const result=favoriteMutation.then(mutate,mutate);favoriteMutation=result.catch(()=>{});return result;
}
async function recordRecent(id) {
  await extensionContext.globalState.update(RECENTS_KEY, [id, ...ids(RECENTS_KEY).filter((value) => value !== id)].slice(0, 12));
  vscode.commands.executeCommand('ikemen.authoring.refreshSidebar');
}

function cards(items) {
  const favoriteIds = new Set(ids(FAVORITES_KEY));
  return items.map((item) => `<article class="card" data-kind="${escape(item.kind)}"><div class="badges"><span>${escape(item.kind)}</span><span>${escape(item.source)}</span><span>${escape(item.compatibility)}</span>${item.ownership ? `<span>Ownership: ${escape(item.ownership)}</span>` : ''}</div><h2>${escape(item.label)}</h2><p>${escape(item.detail)}</p>${item.explanation ? `<p>${escape(item.explanation)}</p>` : ''}${item.modes?.length ? `<details open><summary>Authoring paths (${item.modes.length})</summary><ul>${item.modes.map((value) => `<li><b>${escape(value.label)}</b> — ${escape(value.detail)}</li>`).join('')}</ul></details>` : ''}${item.ownershipLevels?.length ? `<details><summary>Ownership levels (${item.ownershipLevels.length})</summary><ul>${item.ownershipLevels.map((value) => `<li><b>${escape(value.label)}</b> — ${escape(value.detail)}</li>`).join('')}</ul></details>` : ''}${item.parameters?.length ? `<details><summary>Configured move values (${item.parameters.length})</summary><ul>${item.parameters.map((value) => `<li><b>${escape(value.name)}</b>: ${escape(value.value)} · ${escape(value.type)}</li>`).join('')}</ul></details>` : ''}${item.dependencies?.length ? `<details><summary>Required project systems (${item.dependencies.length})</summary><ul>${item.dependencies.map((value) => `<li>${escape(value)}</li>`).join('')}</ul></details>` : ''}${item.validationChecklist?.length ? `<details open><summary>Override responsibility review (${item.validationChecklist.length})</summary><ol>${item.validationChecklist.map((value) => `<li>${escape(value)}</li>`).join('')}</ol></details>` : ''}${item.status ? `<p class="status">${escape(item.status)}</p>` : ''}${item.referenceOnly ? `<p class="status">Reference only${item.sourceFileHint ? ` · ${escape(item.sourceFileHint)}` : ''}${item.symbol ? ` · ${escape(item.symbol)}` : ''}</p>` : ''}<div class="actions"><button data-action="favorite" data-id="${escape(item.id)}">${favoriteIds.has(item.id) ? '★ Favorited' : '☆ Favorite'}</button>${item.kind === 'structure' || (item.kind === 'recipeSection' && (item.snippet || item.structureId)) ? `<button data-action="insert" data-id="${escape(item.id)}">Insert</button>` : ''}${item.kind === 'recipe' ? `<button data-action="openRecipe" data-id="${escape(item.id)}">Explain & sections</button>` : ''}</div></article>`).join('');
}
function intentAliases(nightlyStringsEnabled=false) {
  const configured=vscode?.workspace.getConfiguration('ikemenZss').get('authoring.intentAliases', {}) || {};
  if(nightlyStringsEnabled===true)return configured;
  return Object.fromEntries(Object.entries(configured).filter(([key,value])=>!/(?:^|\W)strings?(?:\W|$)|runtime\s+text/i.test(`${key} ${Array.isArray(value)?value.join(' '):value}`)));
}
