  const source = view === 'examples' ? catalog.EXAMPLE_PACKS : view === 'favorites' ? favorites({nightlyStringsEnabled,capabilities}) : view === 'recipes' ? catalog.recipes({nightlyStringsEnabled,capabilities}) : [];
  const intro = view === 'symbols'
    ? 'Maps, constants, functions, commands, state ranges, helpers, contracts, uses, and validation will share this catalog. Project Maps remains available while the combined index is built.'
    : view === 'examples' ? 'These offline reference packs remain learning material until their manifests, attribution, and compatibility are verified. Project conventions are not IKEMEN requirements.'
    : view === 'favorites' ? 'Favorites selected on any Authoring Catalog page also appear in the State Controllers sidebar.'
    : 'Universal, project-neutral recipes. Whole recipes are explained as named sections; insert only the section you need.';
  const tabs=['recipes','symbols','examples','favorites'];
  const content = `<header><h1 id="libraryTitle">${escape(title)}</h1><nav role="tablist" aria-label="Authoring Library sections">${tabs.map(id=>`<button id="view-${id}" role="tab" aria-controls="items" aria-selected="${id===view}" tabindex="${id===view?0:-1}" data-view="${id}">${id==='symbols'?'Symbols & Contracts':id[0].toUpperCase()+id.slice(1)}</button>`).join('')}</nav><input id="search" value="${escape(query)}" aria-label="Search authoring catalog" placeholder="Try an intent, such as run during hit pause"><button id="intentAliases" title="Add project or personal phrases that should find existing authoring terms">Intent aliases…</button><button id="maps">Open Project Maps</button></header><p id="libraryStatus" class="status" role="status" aria-live="polite">Authoring Library controls are ready.</p><p>${escape(intro)}</p><main class="grid" id="items" role="tabpanel" aria-labelledby="view-${view}">${cards(source) || '<p class="status">No entries are available in this section.</p>'}</main>`;
  const script = `let view=${JSON.stringify(view)},searchTimer=0,busy=false;const tabs=[...document.querySelectorAll('[role="tab"]')],search=document.getElementById('search'),status=document.getElementById('libraryStatus'),busySelector='[role="tab"],#search,button[data-action],button[data-source-id],#maps,#intentAliases,[data-symbol-filter],[data-symbol-category],#symbol-string-role,[data-compare-symbol-name],[data-copy-identifier-name],[data-copy-symbol],[data-preview-symbol-name]';function rememberFocus(kind,value=''){vscode.setState({view,focus:kind,value,selectionStart:search.selectionStart||0,selectionEnd:search.selectionEnd||0,scrollY:window.scrollY||0})}function setBusy(value,message=''){busy=Boolean(value);status.textContent=message||(busy?'Authoring Library action in progress…':'Authoring Library controls are ready.');for(const control of document.querySelectorAll(busySelector)){if(control.dataset.originalTitle===undefined)control.dataset.originalTitle=control.title||'';control.disabled=busy;control.title=busy?'Wait for the current Authoring Library action to finish.':control.dataset.originalTitle}}function chooseTab(button){if(busy)return;clearTimeout(searchTimer);vscode.setState({view:button.dataset.view,focus:'tab',value:button.dataset.view,selectionStart:0,selectionEnd:0,scrollY:0});setBusy(true,'Opening '+button.textContent.trim()+'…');vscode.postMessage({type:'view',view:button.dataset.view})}function runSymbolAction(element,message,label){if(busy)return;const value=[message.type,message.category||'',message.name||message.identity||''].join('|');rememberFocus('symbolAction',value);setBusy(true,label);vscode.postMessage(message)}function restoreCatalogAction(value){const parts=String(value||'').split('|'),action=CSS.escape(parts.shift()||''),id=CSS.escape(parts.join('|'));return document.querySelector('button[data-action="'+action+'"]'+(id?'[data-id="'+id+'"]':''))}function restoreSymbolAction(value){const [type,category,name]=String(value||'').split('|').map(part=>CSS.escape(part));if(type==='compareSymbolUsage')return document.querySelector('[data-compare-symbol-category="'+category+'"][data-compare-symbol-name="'+name+'"]');if(type==='copyIdentifier')return document.querySelector('[data-copy-identifier-category="'+category+'"][data-copy-identifier-name="'+name+'"]');if(type==='previewSymbolRename')return document.querySelector('[data-preview-symbol-category="'+category+'"][data-preview-symbol-name="'+name+'"]');if(type==='copySymbol')return document.querySelector('[data-copy-symbol="'+name+'"]');return null}tabs.forEach((button,index)=>{button.onclick=()=>chooseTab(button);button.onkeydown=event=>{let next=-1;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;if(next>=0){event.preventDefault();tabs[next].focus()}}});document.getElementById('maps').onclick=()=>{if(!busy){rememberFocus('control','maps');setBusy(true,'Opening Project Maps…');vscode.postMessage({type:'maps'})}};document.getElementById('intentAliases').onclick=()=>{if(!busy){rememberFocus('control','intentAliases');setBusy(true,'Opening intent-alias settings…');vscode.postMessage({type:'intentAliases'})}};search.oninput=e=>{rememberFocus('search');clearTimeout(searchTimer);searchTimer=setTimeout(()=>vscode.postMessage({type:'search',query:e.target.value,view}),120)};document.addEventListener('click',e=>{const source=e.target.closest('button[data-source-id]');if(source&&!busy){rememberFocus('source',source.dataset.sourceId);setBusy(true,'Opening the exact indexed source…');vscode.postMessage({type:'openSymbol',sourceId:source.dataset.sourceId});return}const b=e.target.closest('button[data-action]');if(b&&!busy){rememberFocus('action',(b.dataset.action||'')+'|'+(b.dataset.id||''));setBusy(true,'Running '+b.textContent.trim()+'…');const message={type:b.dataset.action};if(b.dataset.id)message.id=b.dataset.id;vscode.postMessage(message)}});addEventListener('message',event=>{if(event.data?.type==='libraryBusy')setBusy(event.data.busy,event.data.status)});const saved=vscode.getState();if(saved?.view===view)queueMicrotask(()=>{let target=saved.focus==='search'?search:saved.focus==='tab'?document.querySelector('[data-view="'+CSS.escape(saved.value||view)+'"]'):saved.focus==='control'?document.getElementById(saved.value):saved.focus==='source'?document.querySelector('[data-source-id="'+CSS.escape(saved.value||'')+'"]'):saved.focus==='action'?restoreCatalogAction(saved.value):saved.focus==='symbolAction'?restoreSymbolAction(saved.value):null;if(!target)target=document.querySelector('[role="tab"][aria-selected="true"]');window.scrollTo(0,Math.max(0,Number(saved.scrollY)||0));target?.focus({preventScroll:true});if(target===search){search.setSelectionRange(Math.min(saved.selectionStart||0,search.value.length),Math.min(saved.selectionEnd||0,search.value.length))}});`;
  return libraryPageShell(content, script);
