async function loadProjectSymbols(seed) {
  const service = require('./map_registry_service').current();
  if (!service) return buildProjectSymbolCatalog([], { resolved: false, label: 'No project context', detail: 'Open a character or project source, then refresh this view.' });
  const scope = service.scope(seed), registry = await service.scan(seed), files = [], failures = [];
  for (const filename of registry.indexedFiles || []) {
    try {
      const document = await vscode.workspace.openTextDocument(vscode.Uri.file(filename));
      if (['zss','ikemen-cns'].includes(require('./map_registry_grammar').textGrammar(document, service.context))) files.push({ filename, text: document.getText() });
    }
    catch (error) { failures.push({ filename, reason: error.message }); }
  }
  const model = buildProjectSymbolCatalog(files, { assignedFiles: scope.scopeFiles?.assigned || [], currentFile:seed?.fsPath||'', label: scope.label, resolved: scope.resolved, detail: registry.detail });
  model.failures.push(...failures, ...(registry.readFailures || []));
  return model;
}
