    const indirectRelationship=(title,values,direction)=>{const rows=(values||[]).filter(value=>value.depth>1);return rows.length?`<details><summary>${title} (${rows.length})</summary><ul class="symbol-sites">${rows.slice(0,30).map(value=>`<li><button data-source-id="${escape(value.sourceId)}">${escape(value.file)}:${value.line+1}</button> ${direction==='in'?`${escape(value.name)} can reach ${escape(item.name)}`:`${escape(item.name)} can reach ${escape(value.name)}`} · ${Number(value.depth)} calls</li>`).join('')}</ul></details>`:'';};
    const stateRelationship=(title,values,direction)=>values?.length?`<details><summary>${title} (${values.length})</summary><ul class="symbol-sites">${values.slice(0,30).map(value=>`<li><button data-source-id="${escape(value.sourceId)}">${escape(value.file)}:${value.line+1}</button> ${direction==='in'?`StateDef ${escape(value.name)} transitions to ${escape(item.name)}`:`${escape(item.name)} transitions to StateDef ${escape(value.name)}`}${value.assigned?' · assigned':''}${value.status&&value.status!=='resolved'?` · ${escape(value.status)}`:''}</li>`).join('')}</ul></details>`:'';
    const stateImpactRelationship=(title,values,direction)=>{const rows=(values||[]).filter(value=>value.depth>1);return rows.length?`<details><summary>${title} (${rows.length})</summary><ul class="symbol-sites">${rows.slice(0,30).map(value=>`<li><button data-source-id="${escape(value.sourceId)}">${escape(value.file)}:${value.line+1}</button> ${direction==='in'?`StateDef ${escape(value.name)} can reach ${escape(item.name)}`:`${escape(item.name)} can reach StateDef ${escape(value.name)}`} · ${Number(value.depth)} transitions</li>`).join('')}</ul></details>`:'';};
    const startRelationships=item.stateStarts?.length?`<details><summary>Starts in StateDef (${item.stateStarts.length})</summary><ul class="symbol-sites">${item.stateStarts.slice(0,30).map(value=>`<li><button data-source-id="${escape(value.sourceId)}">${escape(value.file)}:${value.line+1}</button> Helper ${escape(item.name)} starts in StateDef ${escape(value.name)} · ${escape(value.sourceRole)}${value.assigned?' · assigned':''}${value.status&&value.status!=='resolved'?` · ${escape(value.status)}`:''}</li>`).join('')}</ul></details>`:'';
    const accessRelationship=(title,values,verb)=>values?.length?`<details><summary>${title} (${values.length})</summary><ul class="symbol-sites">${values.slice(0,30).map(value=>`<li><button data-source-id="${escape(value.sourceId)}">${escape(value.file)}:${value.line+1}</button> ${escape(value.kind)} ${escape(value.name)} ${verb} ${escape(item.name)}${value.assigned?' · assigned':''}</li>`).join('')}</ul></details>`:'';
    const authoredDocumentation=item.documentation?.length?`<details><summary>Authored documentation (${item.documentation.length})</summary><ul>${item.documentation.map(value=>`<li>${escape(value)}</li>`).join('')}</ul></details>`:'';
    const visibleMetadata=site=>{const metadata=site.metadata||{},visibility=String(metadata.visibilityCapabilityId||'').toLowerCase(),hideStrings=visibility&&!enabledCapabilities.has(visibility)&&!(visibility==='zss.runtime-strings'&&nightlyStringsEnabled),hideCommand=metadata.commandVisibilityCapabilityId&&!enabledCapabilities.has(String(metadata.commandVisibilityCapabilityId).toLowerCase());return Object.entries(metadata).filter(([key])=>!['visibilityCapabilityId','commandVisibilityCapabilityId'].includes(key)&&(!hideStrings||!key.startsWith('string '))&&(!hideCommand||!['usage','command trigger'].includes(key)));};
    const siteRow=site=>{const metadata=visibleMetadata(site);return `<li><button data-source-id="${escape(site.sourceId)}">${escape(site.file)}:${site.line + 1}</button> ${escape(site.role)}${site.access && site.access !== site.role ? ` · ${escape(site.access)}` : ''}${site.runtimeOwner?` · runtime owner ${escape(site.runtimeOwner)}`:''}${site.ownerName?` · in ${escape(site.ownerKind)} ${escape(site.ownerName)}`:''}${metadata.length?` · ${metadata.map(([key,value])=>`${escape(key)} ${escape(value)}`).join(' · ')}`:''}${nightlyStringsEnabled&&site.valueKind&&site.valueKind!=='unknown'?` · ${escape(site.valueKind)}`:''}${nightlyStringsEnabled&&site.valueSummary?` · ${escape(site.valueSummary)}`:''}${nightlyStringsEnabled&&site.argumentKinds?.length?` · args ${escape(site.argumentKinds.join('/'))}`:''}${nightlyStringsEnabled&&site.argumentSummaries?.length?` (${escape(site.argumentSummaries.join('; '))})`:''}${site.assigned ? ' · assigned' : ''}</li>`;};
    const resourceLifecycle=['helpers','explods','projectiles'].includes(item.category)?[['Creation','creation'],['Mutation','mutation'],['Cleanup','cleanup'],['References','reference']].map(([label,role])=>{const sites=item.sites.filter(site=>site.role===role);return sites.length?`<details ${role==='creation'?'open':''}><summary>${label} (${sites.length})</summary><ul class="symbol-sites">${sites.slice(0,30).map(siteRow).join('')}</ul>${sites.length>30?`<p class="status">${sites.length-30} more ${escape(label.toLowerCase())} occurrence(s); narrow the search.</p>`:''}</details>`:'';}).join(''):'';
    const currentKey=model.currentFile?path.resolve(model.currentFile).toLowerCase():'',scopeGroups=[['Current file',site=>currentKey&&path.resolve(site.filename).toLowerCase()===currentKey],['Current character / assigned',site=>site.assigned&&(!currentKey||path.resolve(site.filename).toLowerCase()!==currentKey)],['Connected / shared sources',site=>!site.assigned&&(!currentKey||path.resolve(site.filename).toLowerCase()!==currentKey)]];
    const scopedOccurrences=scopeGroups.map(([label,predicate])=>{const sites=item.sites.filter(predicate);return`<details><summary>${label} (${sites.length})</summary>${sites.length?`<ul class="symbol-sites">${sites.slice(0,30).map(siteRow).join('')}</ul>${sites.length>30?`<p class="status">${sites.length-30} more occurrence(s) in this scope; narrow the search.</p>`:''}`:'<p class="status">No exact indexed occurrences in this scope.</p>'}</details>`;}).join('');
